把下面基于回调的 loadUser 改写为 async/await 版本，并同步更新两个调用方。要求：1) loadUser 返回 Promise；2) 错误用 try/catch 或 Promise.reject 传播；3) 调用方不再传 callback；4) 保持行为等价。输出三个文件改后的代码块并标注文件名。

// api.js
export function loadUser(id, cb) {
  db.get(id, (err, row) => cb(err, row));
}

// profile.js
import { loadUser } from './api';
export function renderProfile(id) {
  loadUser(id, (err, user) => {
    if (err) return console.error(err);
    console.log(user.name);
  });
}

// list.js
import { loadUser } from './api';
function loadAll(ids) {
  ids.forEach(id => loadUser(id, (e, u) => e ? console.warn(e) : console.log(u)));
}

