// router.js
export async function handleCreate(req, res) {
  const payload = parseBody(req.body);
  const normalized = normalizeUser(payload);
  const saved = await persistUser(normalized);
  res.json({ id: saved.id });
}
function parseBody(b) { return { name: b.name?.trim(), email: b.email?.toLowerCase(), age: Number(b.age) }; }
function normalizeUser(u) { u.name = u.name || 'anon'; u.age = isNaN(u.age) ? null : u.age; return u; }
